type MarkdownHeading = {
  /** The heading level, from 1 (`#`) to 6 (`######`). */
  depth: number
  /** The plain-text content of the heading with all inline formatting stripped. */
  value: string
}

/** ATX heading, e.g. `## Heading` (with an optional closing sequence of hashes). */
const ATX_HEADING = /^(#{1,6})(?:[ \t]+(.*?))?[ \t]*$/
/** Opening or closing fence for a fenced code block (``` or ~~~), with an optional info string. */
const FENCE = /^ {0,3}(`{3,}|~{3,})(.*)$/
/** Closing fence for a fenced code block. A closing fence may not carry an info string. */
const FENCE_CLOSE = /^ {0,3}(`{3,}|~{3,})[ \t]*$/
/** Setext heading underline made of `=` characters, producing a depth-1 heading. */
const SETEXT_H1 = /^ {0,3}=+[ \t]*$/
/** Setext heading underline made of `-` characters, producing a depth-2 heading. */
const SETEXT_H2 = /^ {0,3}-+[ \t]*$/
/** A closing sequence of hashes at the end of an ATX heading, e.g. the trailing `##` in `# Heading ##`. */
const ATX_CLOSING = /[ \t]+#+[ \t]*$/
/** The start of an indented code block (four spaces or a tab). */
const INDENTED_CODE = /^(?: {4}|\t)/

/**
 * Removes inline markdown formatting from a heading so only the plain text remains.
 *
 * Handles bold, italic, inline code, strikethrough, links (keeping the link text),
 * images (keeping the alt text), and raw HTML tags.
 */
const stripInlineFormatting = (text: string): string =>
  text
    // Images first (they share the link syntax but keep the alt text): ![alt](url) -> alt
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Links: [text](url) -> text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Inline code: `code` -> code
    .replace(/`+([^`]*)`+/g, '$1')
    // Strikethrough: ~~text~~ -> text
    .replace(/~~(.*?)~~/g, '$1')
    // Bold: **text** or __text__ -> text (before italic so the double markers win)
    .replace(/(\*\*|__)(.*?)\1/g, '$2')
    // Italic: *text* or _text_ -> text
    .replace(/(\*|_)(.*?)\1/g, '$2')
    // Raw HTML tags: <tag> -> (removed)
    .replace(/<[^>]*>/g, '')
